// Walks the normalised HTML AST and replaces every stand-in with the
// matching Edge node from the side table:
//   - <edge-block data-edge-id="N"> ... </edge-block>
//       → EdgeBlock with branches[i].body filled from children, partitioned
//         at <edge-branch> markers.
//   - <edge-self data-edge-id="N">
//       → EdgeInline / EdgeVoid (whatever was put in the side table).
//   - __EDGE_EXPR_N__ in text → EdgeExpression / EdgeComment node.
//   - __EDGE_EXPR_N__ in attribute value → value becomes a list of strings
//     and EdgeExpression nodes.
//   - Attribute named __edge_expr_N__ (or _N_) → dynamic-attribute marker
//     converted to { name: '__edge_expr__', value: [EdgeExpression] }.

const EXPR_TOKEN_RE = /__EDGE_EXPR_(\d+)__/g
const ATTR_NAME_RE = /^__edge_expr_(\d+)__$/i

export function splice(htmlNodes, sideTable, rawBlocks) {
  const out = []
  for (const node of htmlNodes) {
    pushFlattened(out, spliceNode(node, sideTable, rawBlocks))
  }
  return out
}

function pushFlattened(target, value) {
  if (value == null) return
  if (Array.isArray(value)) {
    for (const v of value) target.push(v)
  } else {
    target.push(value)
  }
}

function spliceNode(node, sideTable, rawBlocks) {
  if (node.type === 'HTMLText') {
    return spliceText(node.value, sideTable)
  }
  if (node.type === 'HTMLComment' || node.type === 'HTMLDoctype') {
    return node
  }
  if (node.type === 'HTMLElement') {
    if (node.name === 'edge-block') {
      return spliceBlock(node, sideTable, rawBlocks)
    }
    if (node.name === 'edge-self') {
      return spliceSelf(node, sideTable)
    }
    if (node.name === 'edge-rawblock') {
      return spliceRawBlock(node, rawBlocks)
    }
    // Plain HTML element: splice attrs + children recursively.
    return {
      ...node,
      attrs: spliceAttrs(node.attrs, sideTable),
      children: splice(node.children, sideTable, rawBlocks),
    }
  }
  return node
}

function spliceRawBlock(element, rawBlocks) {
  const id = findAttrId(element.attrs, 'data-edge-id')
  const rb = rawBlocks?.get(id)
  if (!rb) return null
  return {
    type: 'EdgeRawBlock',
    body: rb.body,
    openSwallow: rb.openSwallow,
    closeSwallow: rb.closeSwallow,
  }
}

function spliceText(value, sideTable) {
  if (!value.includes('__EDGE_EXPR_')) {
    return value === '' ? null : { type: 'HTMLText', value }
  }
  const out = []
  let last = 0
  EXPR_TOKEN_RE.lastIndex = 0
  let m
  while ((m = EXPR_TOKEN_RE.exec(value)) !== null) {
    if (m.index > last) {
      out.push({ type: 'HTMLText', value: value.slice(last, m.index) })
    }
    const id = Number(m[1])
    const node = sideTable.get(id)
    if (node) out.push(node)
    last = m.index + m[0].length
  }
  if (last < value.length) {
    out.push({ type: 'HTMLText', value: value.slice(last) })
  }
  return out
}

function findAttrId(attrs, key) {
  for (const a of attrs) {
    if (a.name === key) return Number(a.value)
  }
  return -1
}

function spliceBlock(element, sideTable, rawBlocks) {
  const id = findAttrId(element.attrs, 'data-edge-id')
  const block = sideTable.get(id)
  if (!block) return null

  // Partition children at <edge-branch> markers.
  const branchChildren = [[]]
  for (const child of element.children) {
    if (child.type === 'HTMLElement' && child.name === 'edge-branch') {
      branchChildren.push([])
      continue
    }
    branchChildren[branchChildren.length - 1].push(child)
  }
  // Pair partitions with branches. If counts disagree, prefer the block
  // side (some branches just have an empty body).
  for (let i = 0; i < block.branches.length; i++) {
    const slice = branchChildren[i] ?? []
    block.branches[i].body = splice(slice, sideTable, rawBlocks)
  }
  return block
}

function spliceSelf(element, sideTable) {
  const id = findAttrId(element.attrs, 'data-edge-id')
  const node = sideTable.get(id)
  return node ?? null
}

function spliceAttrs(attrs, sideTable) {
  const out = []
  for (const attr of attrs) {
    // Dynamic-attribute case: attr name is a masked expression token (the
    // HTML parser lower-cases names by default, so we match the lowered
    // form).
    const m = ATTR_NAME_RE.exec(attr.name)
    if (m) {
      const id = Number(m[1])
      const expr = sideTable.get(id)
      if (expr) {
        out.push({ name: '__edge_expr__', value: [expr] })
        continue
      }
    }
    if (attr.value === null) {
      out.push({ name: attr.name, value: null, valueQuote: attr.valueQuote ?? null })
      continue
    }
    if (!attr.value.includes('__EDGE_EXPR_')) {
      out.push({ name: attr.name, value: attr.value, valueQuote: attr.valueQuote ?? null })
      continue
    }
    // Attribute value with interpolation: convert to a list of strings and
    // EdgeExpression nodes.
    const parts = []
    let last = 0
    EXPR_TOKEN_RE.lastIndex = 0
    let m2
    while ((m2 = EXPR_TOKEN_RE.exec(attr.value)) !== null) {
      if (m2.index > last) parts.push(attr.value.slice(last, m2.index))
      const id = Number(m2[1])
      const expr = sideTable.get(id)
      if (expr) parts.push(expr)
      last = m2.index + m2[0].length
    }
    if (last < attr.value.length) parts.push(attr.value.slice(last))
    out.push({ name: attr.name, value: parts, valueQuote: attr.valueQuote ?? null })
  }
  return out
}
